class TurnFeaturesTracker:
    """Tracks turn features during autoregressive generation with KV cache.

    During prefill (seq_len > 1), returns features for the full input.
    During decode (seq_len == 1), returns features for the current token
    and advances position after the last layer processes it.
    """

